Object.assign(sources,{"boseLetter": ["S. N. Bose National Centre · Bose correspondence archive", "https://www.bose.res.in/Prof.S.N.Bose-Archive/"], "boseLife": ["University of St Andrews · Satyendra Nath Bose", "https://mathshistory.st-andrews.ac.uk/Biographies/Bose/"], "condensateStory": ["Nobel Prize · The 2001 physics prize", "https://www.nobelprize.org/prizes/physics/2001/press-release/"], "noetherExile": ["Bryn Mawr College · Emmy Noether at Bryn Mawr", "https://www.brynmawr.edu/news/assistant-professor-german-qinna-shen-looks-mathematician-emmy-noethers-time-bryn-mawr"], "wuExperiment": ["NIST · The reversal of parity", "https://www.nist.gov/pml/fall-parity/reversal-parity-law-nuclear-physics"], "wuTeam": ["NIST · The experiment and its team", "https://www.nist.gov/blogs/taking-measure/forever-stamp-and-discovery-changed-physics-forever"], "penicillinOxford": ["University of Oxford · The discovery of penicillin", "https://www.path.ox.ac.uk/centenary/the-discovery-of-penicillin/"], "heatleyStory": ["University of Oxford · Norman Heatley", "https://www.ox.ac.uk/giving/stories/norman-heatley-the-unassuming-penicillin-pioneer-who-changed-the-course-of-medicine"], "adaVision": ["Computer History Museum · Ada Lovelace", "https://www.computerhistory.org/babbage/adalovelace/"], "payneThesis": ["Harvard Plate Stacks · Payne’s doctoral thesis", "https://platestacks.cfa.harvard.edu/cecilia-payne-gaposchkin/education-and-doctoral-thesis"], "higgsTeams": ["ATLAS · A landmark discovery", "https://atlas.cern/Discover/Physics/Higgs"], "higgsDay": ["CERN Courier · Ten years after the discovery", "https://cern-courier.web.cern.ch/a/the-higgs-enigma-celebrating-10-years-of-discovery/"], "hodgkinStructure": ["Science History Institute · Florey, Chain and penicillin’s structure", "https://www.sciencehistory.org/education/scientific-biographies/howard-walter-florey-and-ernst-boris-chain/"], "hodgkinModel": ["Oxford History of Science Museum · Modelling penicillin", "https://www.mhs.ox.ac.uk/backfromthedead/exhibition/the-structure-of-penicillin/index.html"], "turingPaper": ["Alan Turing · On computable numbers, 1936", "https://people.csail.mit.edu/brooks/idocs/Turing_Paper_1936.pdf"]});
const additionalNarratives=[{"id": "bose-letter", "title": "The letter Einstein chose to answer", "kicker": "The letter Einstein chose to answer", "category": "Collaboration", "period": "1924 to 1995", "people": ["bose", "einstein", "cornell", "wieman", "ketterle"], "discoveries": ["condensate"], "sources": ["boseLetter", "boseLife", "condensateStory"], "dek": "A physicist in Dhaka sent an unfamiliar way of counting light to the most famous physicist in the world.", "chapters": [["A paper with nowhere to go", "In 1924, Satyendra Nath Bose had a paper about light and a problem getting it published. Working in Dhaka, he had reached Planck’s radiation law by counting light quanta in an unusual way. Instead of leaving the manuscript with a journal that had rejected it, he sent it to Albert Einstein. The accompanying letter asked for help bringing the work before a German scientific readership."], ["An argument crosses a border", "Einstein did more than acknowledge the envelope. He translated the paper and arranged its publication. Bose’s approach treated identical light particles in a way that ordinary counting did not. Einstein then extended the reasoning to atoms, where it suggested a startling possibility: sufficiently cold particles could gather into the same quantum state. A publication problem had become the beginning of a new physical prediction."], ["The long wait for cold enough", "The experimental ending took another seven decades. In 1995, groups led by Eric Cornell and Carl Wieman, and independently Wolfgang Ketterle, produced dilute gas condensates. The apparatus belonged to a different scientific era from Bose’s letter, but the intellectual connection remained. His calculation had travelled from a desk in Dhaka into an experimental state of matter that neither correspondent had lived to see."]], "note": "Bose’s work on light and Einstein’s extension to material particles were distinct contributions. The 1995 experiments involved research teams.", "asset": "bose"}, {"id": "noether-door", "title": "The mathematician without a place in the lecture list", "kicker": "The mathematician without a place in the lecture list", "category": "Recognition", "period": "1915 to 1935", "people": ["noether", "einstein"], "discoveries": ["noether-symmetry", "general-relativity"], "sources": ["noether", "noetherExile"], "dek": "Göttingen needed Emmy Noether’s mathematics. Giving her the right to teach was another matter.", "chapters": [["Invited, but not admitted", "In 1915, David Hilbert and Felix Klein invited Emmy Noether to Göttingen. Questions raised by relativity needed precisely the mathematics she understood. Yet the university resisted granting a woman the qualification required to teach independently. Noether could help untangle the foundations of physics while her lectures appeared under Hilbert’s name. The obstacle was not a missing proof."], ["What symmetry keeps", "The work led to her 1918 results linking continuous symmetries with conservation laws. An apparent collection of separate rules about what nature preserves could be understood through the transformations that leave a physical description unchanged. In 1919 she finally received permission to qualify as a university lecturer. Formal recognition followed the research rather than making it possible."], ["Another departure", "In 1933 the Nazi government forced her out because she was Jewish. Colleagues and an organisation supporting displaced scholars helped her reach Bryn Mawr in the United States. She taught there until her death in 1935. The move protected a brief final chapter of her working life. Her mathematics travelled further, through her students, abstract algebra and the language of modern physics."]], "note": "This account separates institutional exclusion from mathematical recognition. No dialogue or private reactions are reconstructed.", "asset": "noether"}, {"id": "wu-mirror", "title": "The experiment that broke nature’s mirror", "kicker": "The experiment that broke nature’s mirror", "category": "Discovery", "period": "1956 to 1957", "people": ["wu", "lee", "yang"], "discoveries": ["parity"], "sources": ["wuExperiment", "wuTeam"], "dek": "Lee and Yang asked whether a familiar symmetry had ever been tested properly. Chien Shiung Wu made the question experimental.", "chapters": [["A rule without the right test", "In 1956, Tsung Dao Lee and Chen Ning Yang challenged an assumption: perhaps the weak interaction did not behave identically in a mirror. The idea concerned real experiments, not merely how equations looked on paper. They turned to Chien Shiung Wu, whose command of radioactive decay made her an unusually strong guide to a difficult test."], ["Cold enough to ask clearly", "Wu worked with Ernest Ambler, Raymond Hayward, Dale Hoppes and Ralph Hudson at the US National Bureau of Standards. The team needed cobalt nuclei aligned at extremely low temperatures, then had to count how electrons emerged as those nuclei decayed. If the electrons preferred one direction relative to the nuclear spin, the mirror symmetry would fail. The apparatus made an abstract doubt measurable."], ["The answer and the names", "The results emerged around the end of 1956 and were reported in 1957. The electrons did show a preferred direction. A principle treated as dependable had failed in a specific part of nature. Lee and Yang received that year’s physics Nobel Prize. Wu and the experimental team did not share it. The experiment’s history therefore carries two stories together: how a symmetry was tested, and how a discovery’s credit was divided."]], "note": "Parity violation here concerns the weak interaction. The experiment was a collaboration between Wu and the Bureau’s low temperature group.", "asset": "wu"}, {"id": "penicillin-shortage", "title": "The medicine that ran out", "kicker": "The medicine that ran out", "category": "Collaboration", "period": "1928 to 1945", "people": ["fleming", "florey", "chain", "heatley"], "discoveries": ["penicillin-observed", "penicillin-treatment"], "sources": ["penicillinOxford", "heatleyStory"], "dek": "Finding a mould that killed bacteria was only the beginning. Making enough medicine became a race of its own.", "chapters": [["An observation waits", "Alexander Fleming noticed the effect of a contaminating mould on bacteria in 1928. But a promising patch on a culture plate was not a treatment that hospitals could reliably use. Years later in Oxford, Howard Florey’s group returned to penicillin. Ernst Chain helped make it a research programme; Norman Heatley helped turn awkward biological material into something the team could extract and test."], ["A patient improves", "Animal experiments in 1940 gave the team a reason to attempt treatment. In 1941 the Oxford researchers treated the seriously infected policeman Albert Alexander. His condition initially improved. Then the available penicillin was exhausted, and he later died. The episode exposed the gulf between a substance that worked and a supply capable of sustaining treatment. More ingenious laboratory work alone would not be enough."], ["A discovery becomes an industry", "Florey and Heatley travelled to the United States in 1941 to seek help with production. Laboratories, government agencies and manufacturers became part of the story. Fermentation and processing had to work at an entirely different scale. By the time Fleming, Florey and Chain shared the 1945 Nobel Prize, penicillin’s success depended on a much wider cast, including people whose names rarely appear beside the original mould."]], "note": "Alexander was an early Oxford patient, not the first person ever exposed to penicillin. Many researchers and production workers contributed to the treatment’s development.", "asset": "fleming"}, {"id": "ada-notes-story", "title": "The notes that outgrew the machine", "kicker": "The notes that outgrew the machine", "category": "Collaboration", "period": "1833 to 1843", "people": ["ada", "babbage"], "discoveries": ["ada-notes"], "sources": ["adaVision", "babbage"], "dek": "Ada Lovelace began with a translation. She ended with an argument for what a calculating machine might become.", "chapters": [["A small working piece", "In 1833, seventeen year old Ada met Charles Babbage and saw a working section of his calculating engine. Their later correspondence connected his plans for machinery with her mathematical education. The Analytical Engine that followed was far more ambitious than a table making device, but it remained a proposed machine. Understanding its possibilities required imagination disciplined by the mechanisms Babbage intended to build."], ["The translator takes the page", "In 1843, Lovelace translated Luigi Menabrea’s account of the Analytical Engine from French. She added extensive notes developed in close exchange with Babbage. Among them was a sequence of operations for calculating Bernoulli numbers. The extra material made the translation a vehicle for exploring the machine rather than simply reporting what another writer had said about it."], ["Beyond arithmetic", "Lovelace’s larger claim was that numbers could stand for things other than quantities. If relationships could be represented through symbols, a machine might work on those relationships too, even in music. The Engine was never completed in their lifetimes. What survived was a description of possible computation, attached to unrealised machinery, written by someone who recognised that calculation need not be its final boundary."]], "note": "The title “first programmer” and the division of work with Babbage require care. Their collaboration is documented; this story does not assign every detail to one author.", "asset": "ada"}, {"id": "kepler-mars", "title": "The planet that would not fit", "kicker": "The planet that would not fit", "category": "Discovery", "period": "1600 to 1609", "people": ["kepler", "brahe"], "discoveries": ["ellipses", "planet-laws"], "sources": ["kepler", "keplerLaws"], "dek": "Tycho Brahe had the observations. Johannes Kepler had to make Mars obey a mathematical description.", "chapters": [["An inheritance of measurements", "When Johannes Kepler joined Tycho Brahe in Prague around 1600, he entered a world built on extraordinarily careful observation. Brahe assigned him the problem of Mars. After Brahe’s death in 1601, Kepler’s work continued with the observational record at its centre. The data were precious because a theory could now fail against measurements precise enough to expose its weaknesses."], ["The long calculation", "Mars refused to settle into the description Kepler wanted. Working from observations made on a moving Earth meant laborious geometry before the planet’s own path could even be investigated. He explored and rejected possible curves. This was not a moment of casually replacing a circle with an oval. The eventual ellipse emerged from sustained attempts to reconcile geometry, physical reasoning and the observations."], ["A different sort of order", "In Astronomia Nova, published in 1609, Kepler presented the elliptical path and a rule connecting time with the area swept out from the Sun. A planet could change speed along its orbit while remaining mathematically orderly. Brahe’s observational craft and Kepler’s theoretical work had produced something neither part could supply alone: a description accurate enough to reshape planetary astronomy."]], "note": "Kepler’s reasoning was more complex than a simple guess of an ellipse. Brahe’s observations and Kepler’s interpretation are treated as distinct achievements.", "asset": "kepler"}, {"id": "wegener-continents", "title": "The continents that refused to stay still", "kicker": "The continents that refused to stay still", "category": "Debate", "period": "1912 to the 1960s", "people": ["wegener"], "discoveries": ["continental-drift", "seafloor", "magnetic-stripes", "plate-tectonics"], "sources": ["geology", "plates"], "dek": "Alfred Wegener assembled a case for moving continents. He could not supply a convincing engine to move them.", "chapters": [["Pieces of a former world", "In 1912, meteorologist Alfred Wegener argued that continents had once belonged to a larger landmass. Coastlines were part of the attraction, but his case also brought together fossils, rocks and signs of ancient climates on lands now separated by oceans. Each similarity asked the same question: were the continents fixed, or was the map itself part of Earth’s history?"], ["The missing mechanism", "The evidence did not settle the argument. Critics asked how enormous continents could move through the material beneath them. Wegener’s proposed forces did not provide a satisfactory answer. His theory therefore contained a productive tension: a substantial pattern of observations, paired with an explanation of motion that did not work. Accepting the pattern did not require accepting every part of the proposed mechanism."], ["The answer beneath the sea", "Wegener died in 1930, before ocean floor research transformed the debate. Later discoveries of spreading seafloor, magnetic patterns and plate boundaries supplied a different framework. Continents travelled as parts of moving plates, rather than simply ploughing through a fixed ocean floor. The eventual theory preserved a central insight while changing the machinery of the explanation. Vindication came with revision."]], "note": "Modern plate tectonics is not identical to Wegener’s original theory. His proposed driving mechanisms did not survive unchanged.", "asset": "wegener"}, {"id": "oxygen-argument", "title": "The same gas, two different worlds", "kicker": "The same gas, two different worlds", "category": "Debate", "period": "1770s to 1780s", "people": ["priestley", "lavoisier", "marieanne"], "discoveries": ["oxygen", "combustion", "chemistry-elements"], "sources": ["priestley", "lavoisier"], "dek": "Priestley produced a remarkable gas. The Lavoisiers helped make it part of a different account of chemistry.", "chapters": [["A flame burns differently", "Joseph Priestley’s experiments in 1774 produced a gas in which burning and breathing behaved unusually well. He described it through phlogiston theory, the framework he already used to understand combustion. An unfamiliar result had appeared, but it did not arrive carrying its own explanation. Another chemist could reproduce the effect and still disagree about what had happened."], ["The balance changes the question", "Antoine Lavoisier treated the gas as a constituent of air that combined with substances during combustion. Careful weighing helped shift the explanation from something escaping a burning body to something joining it. Marie Anne Paulze Lavoisier contributed translations, records and illustrations to their scientific work. The change in chemistry depended on communication and representation as well as experiments."], ["An argument becomes a language", "Oxygen became central to the new account, and a revised chemical vocabulary made that account teachable. Priestley did not simply abandon his older interpretation. The discovery story consequently resists a single clean handover from error to truth. Producing a gas, identifying its role and persuading others to organise chemistry around it were different achievements, carried out by people who did not all agree."]], "note": "Carl Wilhelm Scheele also independently prepared oxygen. This episode focuses on Priestley and the Lavoisiers rather than assigning the entire discovery to one experiment.", "asset": "lavoisier"}, {"id": "payne-stars", "title": "The answer she was told to doubt", "kicker": "The answer she was told to doubt", "category": "Recognition", "period": "1925 to 1929", "people": ["payne"], "discoveries": ["stellar-composition"], "sources": ["payneThesis"], "dek": "Cecilia Payne’s thesis suggested that stars were overwhelmingly hydrogen and helium. The conclusion seemed too large to accept.", "chapters": [["Starlight becomes evidence", "At Harvard, Cecilia Payne used stellar spectra and developing atomic theory to investigate what stars were made of. Her 1925 thesis pointed to extraordinary abundances of hydrogen and helium. Stars no longer looked like Earth heated until it glowed."], ["Authority enters the thesis", "Henry Norris Russell urged caution about the result. Payne included language retreating from the enormous abundances her analysis had produced. The published work therefore preserved a striking contradiction: the evidence for a new picture of the stars, alongside a warning against taking its strongest implication literally. "], ["The conclusion returns", "In 1929, Russell’s own work endorsed the high hydrogen abundance. Payne’s result had survived the doubt placed around it. The episode is about more than a delayed correction: it shows how evidence and professional authority can move at different speeds, and how a discovery can already be on the page before a field is ready to recognise it."]], "note": "Accounts differ about Russell’s motives. The documented caution and later confirmation do not require inventing his private intentions.", "asset": "payne"}, {"id": "hodgkin-structure", "title": "The crystal that settled an argument", "kicker": "The crystal that settled an argument", "category": "Discovery", "period": "1940s", "people": ["hodgkin", "chain"], "discoveries": ["protein-crystal", "penicillin-treatment"], "sources": ["hodgkin", "hodgkinStructure", "hodgkinModel"], "dek": "Penicillin could save lives before chemists agreed on its structure. Dorothy Hodgkin’s team asked the crystals.", "chapters": [["A medicine with an unresolved shape", "As penicillin became a practical treatment, its atomic arrangement remained disputed. Chemical reasoning produced competing proposed structures. The question mattered because knowing what a molecule did was different from knowing how its atoms were joined. At Oxford, Dorothy Crowfoot Hodgkin approached the problem through the patterns made when X rays met crystals of penicillin salts."], ["A pattern is not a photograph", "The scattered rays did not provide a convenient picture of a molecule. Turning their patterns into an arrangement of atoms required measurements, calculations and the work of collaborators. Barbara Low worked with Hodgkin, while other contributions came from researchers including C. W. Bunn and A. Turner Jones. A model built from electron density made an otherwise invisible structure something the team could examine."], ["Evidence changes the dispute", "In 1945 the crystallographic result supported the structure proposed by Chain and Edward Abraham over the alternative associated with Robert Robinson. The argument could be tested against physical evidence rather than reputation alone. Hodgkin’s work did not replace the efforts that had made penicillin a medicine; it answered another question about the same substance, adding a structural explanation to a therapeutic achievement."]], "note": "The structure determination was collaborative. The model shown is an archival object associated with the work, not a direct photograph of individual atoms.", "asset": "hodgkin-model"}, {"id": "turing-paper", "title": "The machine made out of a question", "kicker": "The machine made out of a question", "category": "Discovery", "period": "1936 to 1938", "people": ["turing", "church"], "discoveries": ["turing-machine"], "sources": ["turingPaper", "churchTuring"], "dek": "Before a universal computer was hardware, Alan Turing used an imaginary machine to investigate the limits of calculation.", "chapters": [["What does following a rule mean?", "In 1936, Alan Turing approached a mathematical problem by stripping calculation down to elementary actions. Imagine a device reading symbols from a tape, changing a symbol and moving according to a fixed table of rules. The machine was an argument on paper. Its simplicity made it possible to ask precisely what a mechanical procedure could accomplish."], ["One machine reads another", "Turing described how a universal machine could use an encoded description to carry out the work of other machines. Instructions could themselves become symbols to be read. Yet this power came with a limit: no general mechanical method could decide every mathematical question of the required kind. The same paper made computation look remarkably general and demonstrated that generality was not omnipotence."], ["An independent answer becomes a connection", "Alonzo Church had reached a related negative result through a different formal approach. Turing went to Princeton, where Church supervised his doctoral work, completed in 1938. Independent reasoning became a research relationship. The paper’s enduring machine was never tied to one particular mechanism; it offered a way to describe computation across machines that would be built much later."]], "note": "A Turing machine is a mathematical model. The history of practical computers involved many other people, projects and engineering decisions.", "asset": "turing"}, {"id": "higgs-wait", "title": "Forty eight years to find a particle", "kicker": "Forty eight years to find a particle", "category": "Collaboration", "period": "1964 to 2012", "people": ["higgs", "englert", "brout", "kibble", "guralnik", "hagen"], "discoveries": ["higgs-mechanism", "higgs-detected"], "sources": ["higgsTeams", "higgsDay"], "dek": "A small set of theoretical papers became a question that required enormous machines and thousands of people.", "chapters": [["Several routes to a mechanism", "In 1964, Robert Brout and François Englert, Peter Higgs, and Gerald Guralnik, Carl Hagen and Tom Kibble developed related solutions to a problem in particle theory. A field could allow certain particles to acquire mass while preserving the structure the theory needed. The papers were separate contributions to a common difficulty. The particle associated with the mechanism offered a possible experimental test."], ["The people who had to build the answer", "Finding that particle required more than waiting for a fortunate collision. Accelerators had to reach the necessary energies; detectors had to identify the debris; computing and analysis had to separate rare patterns from immense backgrounds. ATLAS and CMS pursued the question through independent experiments at CERN. Their scale made discovery a shared technical achievement, distributed across institutions and countries."], ["A room hears the result", "On 4 July 2012, the collaborations announced a new particle consistent with the expected Higgs boson. Some of the theorists were in the audience. Brout, who had died the previous year, was not. Later measurements strengthened the identification. A result often attached to one surname had joined decades of theory to the work of thousands, making the announcement both a scientific answer and a meeting of generations."]], "note": "The 2012 announcement initially described a new boson consistent with the Higgs prediction. Subsequent measurements tested its properties. The field does not account for all mass in ordinary matter.", "asset": "higgs"}];
narratives.splice(1,0,...additionalNarratives);
Object.assign(visualAssets,{"bose": {"src": "images/bose.jpg", "width": 776, "height": 780, "caption": "Satyendra Nath Bose in Kolkata in 1915, before his 1924 correspondence with Einstein.", "alt": "Satyendra Nath Bose in Kolkata in 1915, before his 1924 correspondence with Einstein.", "credit": "Unknown author (Courtesy of Falguni Sarkar/The S.N. Bose Project). Via Wikimedia Commons. Image resized; card thumbnails may be cropped.", "source": "https://commons.wikimedia.org/wiki/File:Satyendra-nath-bose.jpg", "license": "Public domain", "licenseUrl": "https://commons.wikimedia.org/wiki/File:Satyendra-nath-bose.jpg"}, "noether": {"src": "images/noether.jpg", "width": 1208, "height": 1840, "caption": "Emmy Noether in an early portrait, circa 1900, before her work in Göttingen.", "alt": "Emmy Noether in an early portrait, circa 1900, before her work in Göttingen.", "credit": "Unknown author\n\nPublisher: Mathematical Association of America [3], Brooklyn Museum [4], Agnes Scott College [5], [6]. Via Wikimedia Commons. Image resized; card thumbnails may be cropped.", "source": "https://commons.wikimedia.org/wiki/File:Emmy_Noether.jpg", "license": "Public domain", "licenseUrl": "https://commons.wikimedia.org/wiki/File:Emmy_Noether.jpg"}, "wu": {"src": "images/wu.jpg", "width": 1280, "height": 1624, "caption": "Chien Shiung Wu in 1958, following the parity experiment. This portrait was cropped from a Science Talent Search group photograph.", "alt": "Chien Shiung Wu in 1958, following the parity experiment. This portrait was cropped from a Science Talent Search group photograph.", "credit": "Smithsonian Institution from United States. Via Wikimedia Commons. Image resized; card thumbnails may be cropped.", "source": "https://commons.wikimedia.org/wiki/File:Chien-Shiung_Wu_(1912-1997)_in_1958.jpg", "license": "No known copyright restrictions, as listed by the Smithsonian", "licenseUrl": "https://www.flickr.com/commons/usage/"}, "fleming": {"src": "images/fleming.jpg", "width": 280, "height": 396, "caption": "Alexander Fleming in 1945. The discovery of the mould’s antibacterial action preceded the Oxford team’s development of penicillin as a treatment.", "alt": "Alexander Fleming in 1945. The discovery of the mould’s antibacterial action preceded the Oxford team’s development of penicillin as a treatment.", "credit": "Nobel Foundation. Via Wikimedia Commons. Image resized; card thumbnails may be cropped.", "source": "https://commons.wikimedia.org/wiki/File:Alexander_Fleming_1945.jpg", "license": "Public domain", "licenseUrl": "https://commons.wikimedia.org/wiki/File:Alexander_Fleming_1945.jpg"}, "higgs": {"src": "images/higgs.jpg", "width": 640, "height": 640, "caption": "Peter Higgs at a chalkboard in a later photograph. This is not a photograph of the 1964 theoretical work or the 2012 discovery announcement.", "alt": "Peter Higgs at a chalkboard in a later photograph. This is not a photograph of the 1964 theoretical work or the 2012 discovery announcement.", "credit": "Hans G. Via Wikimedia Commons. Image resized; card thumbnails may be cropped.", "source": "https://commons.wikimedia.org/wiki/File:Peter_higgs_chalkboard.jpg", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0"}, "ada": {"src": "images/ada.jpg", "width": 1280, "height": 1839, "caption": "Ada Lovelace in a watercolour portrait by Alfred Edward Chalon, circa 1840.", "alt": "Ada Lovelace in a watercolour portrait by Alfred Edward Chalon, circa 1840.", "credit": "Alfred Edward Chalon. Via Wikimedia Commons. Image resized; card thumbnails may be cropped.", "source": "https://commons.wikimedia.org/wiki/File:Ada_Lovelace_portrait.jpg", "license": "Public domain", "licenseUrl": "https://commons.wikimedia.org/wiki/File:Ada_Lovelace_portrait.jpg"}, "kepler": {"src": "images/kepler.jpg", "width": 1258, "height": 1689, "caption": "An archival reproduction of a portrait of Johannes Kepler, held in the Wellcome collection.", "alt": "An archival reproduction of a portrait of Johannes Kepler, held in the Wellcome collection.", "credit": "Unknown author. Via Wikimedia Commons. Image resized; card thumbnails may be cropped.", "source": "https://commons.wikimedia.org/wiki/File:Portrait_of_Johannes_Kepler.jpg", "license": "Public domain", "licenseUrl": "https://commons.wikimedia.org/wiki/File:Portrait_of_Johannes_Kepler.jpg"}, "wegener": {"src": "images/wegener.jpg", "width": 1224, "height": 1480, "caption": "Alfred Wegener in a portrait dated between 1924 and 1930, after he proposed continental drift.", "alt": "Alfred Wegener in a portrait dated between 1924 and 1930, after he proposed continental drift.", "credit": "Unknown author. Via Wikimedia Commons. Image resized; card thumbnails may be cropped.", "source": "https://commons.wikimedia.org/wiki/File:Alfred_Wegener_ca.1924-30.jpg", "license": "Public domain", "licenseUrl": "https://commons.wikimedia.org/wiki/File:Alfred_Wegener_ca.1924-30.jpg"}, "lavoisier": {"src": "images/lavoisier.jpg", "width": 385, "height": 599, "caption": "An engraved portrait of Antoine Lavoisier from the University of Dundee Museum Collections.", "alt": "An engraved portrait of Antoine Lavoisier from the University of Dundee Museum Collections.", "credit": "University of Dundee Museum Services. Via Wikimedia Commons. Image resized; card thumbnails may be cropped.", "source": "https://commons.wikimedia.org/wiki/File:Antoine_Lavoisier.jpg", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0"}, "payne": {"src": "images/payne.jpg", "width": 1280, "height": 987, "caption": "Cecilia Payne Gaposchkin at Harvard College Observatory. The date of this archival photograph is uncertain.", "alt": "Cecilia Payne Gaposchkin at Harvard College Observatory. The date of this archival photograph is uncertain.", "credit": "Smithsonian Institution/Science Service, restored by Adam Cuerden. Via Wikimedia Commons. Image resized; card thumbnails may be cropped.", "source": "https://commons.wikimedia.org/wiki/File:Cecilia_Helena_Payne-Gaposchkin_(1900-1979)_-_Science_Service.jpg", "license": "Public domain", "licenseUrl": "https://commons.wikimedia.org/wiki/File:Cecilia_Helena_Payne-Gaposchkin_(1900-1979)_-_Science_Service.jpg"}, "turing": {"src": "images/turing.jpg", "width": 800, "height": 1067, "caption": "Alan Turing photographed by Elliott and Fry on 29 March 1951, well after his 1936 paper on computable numbers.", "alt": "Alan Turing photographed by Elliott and Fry on 29 March 1951, well after his 1936 paper on computable numbers.", "credit": "Elliott & Fry. Via Wikimedia Commons. Image resized; card thumbnails may be cropped.", "source": "https://commons.wikimedia.org/wiki/File:Alan_Turing_(1951).jpg", "license": "Public domain", "licenseUrl": "https://commons.wikimedia.org/wiki/File:Alan_Turing_(1951).jpg"}, "hodgkin-model": {"src": "images/hodgkin-model.jpeg", "width": 1280, "height": 1060, "caption": "A model of penicillin’s structure, circa 1945. It represents electron density from crystallographic work by Dorothy Hodgkin, Barbara Low, C. W. Bunn and A. Turner Jones.", "alt": "A model of penicillin’s structure, circa 1945. It represents electron density from crystallographic work by Dorothy Hodgkin, Barbara Low, C. W. Bunn and A. Turner Jones.", "credit": "Museum of the History of Science, University of Oxford. Via Wikimedia Commons. Image resized; card thumbnails may be cropped.", "source": "https://commons.wikimedia.org/wiki/File:Model_of_the_Structure_of_Penicillin,_by_Dorothy_Hodgkin,_Oxford,_c.1945.jpeg", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0"}});
for(const s of additionalNarratives){storyVisuals[s.id]={hero:s.asset,chapters:{}};const subject=s.people[0];if(s.asset!=='hodgkin-model')personVisuals[subject]=s.asset;}
discoveryVisuals['protein-crystal']='hodgkin-model';
